229	  /**
230	   * Tests enable/disable Storage Policy Satisfier dynamically when
231	   * "dfs.storage.policy.enabled" feature is disabled.
232	   *
233	   * @throws ReconfigurationException
234	   * @throws IOException
235	   */
236	  @Test(timeout = 30000)
237	  public void testReconfigureSPSWithStoragePolicyDisabled()
238	      throws ReconfigurationException, IOException {
239	    // shutdown cluster
240	    cluster.shutdown();
241	    Configuration conf = new HdfsConfiguration();
242	    conf.setBoolean(DFSConfigKeys.DFS_STORAGE_POLICY_ENABLED_KEY, false);
243	    cluster = new MiniDFSCluster.Builder(conf).build();
244	    cluster.waitActive();
245	
246	    final NameNode nameNode = cluster.getNameNode();
247	    verifySPSEnabled(nameNode, DFS_STORAGE_POLICY_SATISFIER_MODE_KEY,
248	        StoragePolicySatisfierMode.NONE, false);
249	
250	    // enable SPS internally by keeping DFS_STORAGE_POLICY_ENABLED_KEY
251	    nameNode.reconfigureProperty(DFS_STORAGE_POLICY_SATISFIER_MODE_KEY,
252	        StoragePolicySatisfierMode.EXTERNAL.toString());
253	
254	    // Since DFS_STORAGE_POLICY_ENABLED_KEY is disabled, SPS can't be enabled.
255	    assertNull("SPS shouldn't start as "
256	        + DFSConfigKeys.DFS_STORAGE_POLICY_ENABLED_KEY + " is disabled",
257	            nameNode.getNamesystem().getBlockManager().getSPSManager());
258	    verifySPSEnabled(nameNode, DFS_STORAGE_POLICY_SATISFIER_MODE_KEY,
259	        StoragePolicySatisfierMode.EXTERNAL, false);
260	
261	    assertEquals(DFS_STORAGE_POLICY_SATISFIER_MODE_KEY + " has wrong value",
262	        StoragePolicySatisfierMode.EXTERNAL.toString(), nameNode.getConf()
263	            .get(DFS_STORAGE_POLICY_SATISFIER_MODE_KEY,
264	            DFS_STORAGE_POLICY_SATISFIER_MODE_DEFAULT));
265	  }
