310	  @Test(timeout = 30000)
311	  public void testSatisfyStoragePolicyAfterSatisfierDisabled()
312	      throws ReconfigurationException, IOException {
313	    final NameNode nameNode = cluster.getNameNode();
314	
315	    // disable SPS
316	    nameNode.reconfigureProperty(DFS_STORAGE_POLICY_SATISFIER_MODE_KEY,
317	        StoragePolicySatisfierMode.NONE.toString());
318	    verifySPSEnabled(nameNode, DFS_STORAGE_POLICY_SATISFIER_MODE_KEY,
319	        StoragePolicySatisfierMode.NONE, false);
320	
321	    Path filePath = new Path("/testSPS");
322	    DistributedFileSystem fileSystem = cluster.getFileSystem();
323	    fileSystem.create(filePath);
324	    fileSystem.setStoragePolicy(filePath, "COLD");
325	    try {
326	      fileSystem.satisfyStoragePolicy(filePath);
327	      fail("Expected to fail, as storage policy feature has disabled.");
328	    } catch (RemoteException e) {
329	      GenericTestUtils
330	          .assertExceptionContains("Cannot request to satisfy storage policy "
331	              + "when storage policy satisfier feature has been disabled"
332	              + " by admin. Seek for an admin help to enable it "
333	              + "or use Mover tool.", e);
334	    }
335	  }
